#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;

long long modPow(long long base, long long exp) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1)
            result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

long long modInverse(long long a, int m) {
    return modPow(a, m - 2);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long k;
    cin >> n >> k;
    if (k >= n) {
        cout << 0 << "\n";
        return 0;
    }
    vector<long long> fact(n + 1, 1);
    for (int i = 1; i <= n; i++) {
        fact[i] = (fact[i - 1] * i) % MOD;
    }
    if (k == 0) {
        cout << fact[n] << "\n";
        return 0;
    }
    int c = n - k;
    long long invFactC = modInverse(fact[c], MOD);
    long long invFactNMinusC = modInverse(fact[n - c], MOD);
    long long ans = fact[n] * invFactC % MOD * invFactNMinusC % MOD;
    long long sum = 0;
    for (int i = 0; i <= c; i++) {
        long long term;
        if (i % 2 == 0) {
            term = fact[c] * modInverse(i, MOD) % MOD;
            term = term * modInverse(c - i, MOD) % MOD;
            term = term * modPow(c - i, n) % MOD;
            sum = (sum + term) % MOD;
        } else {
            long long temp = fact[c] * modInverse(i, MOD) % MOD;
            temp = temp * modInverse(c - i, MOD) % MOD;
            temp = temp * modPow(c - i, n) % MOD;
            sum = (sum - temp + MOD) % MOD;
        }
    }
    ans = ans * 2 % MOD * sum % MOD;
    cout << ans << "\n";
    return 0;
}

